using System.Text.RegularExpressions;
using Lokad.Utf8Regex.Internal.FrontEnd;

namespace Lokad.Utf8Regex.Tests;

// Owned character-class tables and constants: wire indices and payload bytes
// are pinned; positive constants, word tables, and case conversion check
// against BCL shorthands and character APIs. Wire-query and matching batteries
// below harvest owned payloads against pinned decoder facts and BCL matching.
public sealed class Utf8OwnedCharClassTests
{
    public static IEnumerable<object?[]> WireCases()
    {
        yield return new object?[] { "[a]", 512 };
        yield return new object?[] { "[ab]", 512 };
        yield return new object?[] { "[a-z]", 512 };
        yield return new object?[] { "[^a]", 512 };
        yield return new object?[] { "[a-]", 512 };
        yield return new object?[] { "[-a]", 512 };
        yield return new object?[] { "[--0]", 512 };
        yield return new object?[] { "[\\d]", 512 };
        yield return new object?[] { "[^\\d]", 512 };
        yield return new object?[] { "\\d", 512 };
        yield return new object?[] { "\\D", 512 };
        yield return new object?[] { "\\w", 512 };
        yield return new object?[] { "\\W", 512 };
        yield return new object?[] { "\\s", 512 };
        yield return new object?[] { "\\S", 512 };
        yield return new object?[] { "\\p{L}", 512 };
        yield return new object?[] { "\\p{Lu}", 512 };
        yield return new object?[] { "\\p{IsGreek}", 512 };
        yield return new object?[] { ".", 512 };
        yield return new object?[] { "(?s:.)", 512 };
        yield return new object?[] { "[a-[b]]", 512 };
        yield return new object?[] { "[\\da-z]", 512 };
        yield return new object?[] { "[a\\w]", 512 };
        yield return new object?[] { "[^\\W]", 512 };
        yield return new object?[] { "[\\p{L}a]", 512 };
        yield return new object?[] { "[a-zA-Z0-9]", 512 };
        yield return new object?[] { "[\\x00-\\x7F]", 512 };
        yield return new object?[] { "[é]", 512 };
        yield return new object?[] { "[α-ω]", 512 };
        yield return new object?[] { "[\\b]", 512 };
        yield return new object?[] { "[a\\b]", 512 };
        yield return new object?[] { "[(]", 512 };
        yield return new object?[] { "[)]", 512 };
        yield return new object?[] { "[\\[]", 512 };
        yield return new object?[] { "[\\\\]", 512 };
        yield return new object?[] { "[\\^]", 512 };
        yield return new object?[] { "[a^]", 512 };
        yield return new object?[] { "[^a-z]", 512 };
        yield return new object?[] { "[a-z-[aeiou]]", 512 };
        yield return new object?[] { "\\p{IsBasicLatin}", 512 };
        yield return new object?[] { "\\p{_xmlC}", 512 };
        yield return new object?[] { "\\d", 768 };
        yield return new object?[] { "\\s", 768 };
        yield return new object?[] { "\\w", 768 };
        yield return new object?[] { ".", 768 };
        yield return new object?[] { "[a]", 768 };
        yield return new object?[] { "[^a]", 768 };
    }


    [Theory]
    [MemberData(nameof(WireCases))]
    public void WireQueriesMatchPinnedFacts(string pattern, int options)
    {
        var parsed = Utf8OwnedTreeParser.TryParse(pattern, (RegexOptions)options);
        Assert.NotNull(parsed);
        foreach (var payload in HarvestSetPayloads(parsed.Root))
        {
            AssertWireQueriesEqualPinned(payload);
        }

        AssertWireQueriesEqualPinned(string.Empty);
        AssertWireQueriesEqualPinned("a");
        AssertWireQueriesEqualPinned(new string((char)0, 3));
        AssertWireQueriesEqualPinned(new string((char)0, 4));
    }

    private static System.Collections.Generic.List<string> HarvestSetPayloads(Utf8TreeNode root)
    {
        var payloads = new System.Collections.Generic.List<string>();
        var stack = new System.Collections.Generic.Stack<Utf8TreeNode>();
        stack.Push(root);
        while (stack.Count > 0)
        {
            var node = stack.Pop();
            if ((node.Kind == Utf8TreeNodeKind.Set ||
                node.Kind == Utf8TreeNodeKind.Setloop ||
                node.Kind == Utf8TreeNodeKind.Setlazy) &&
                node.Str is not null)
            {
                payloads.Add(node.Str);
            }

            for (var i = 0; i < node.ChildCount; i++)
            {
                stack.Push(node.Child(i));
            }
        }

        return payloads;
    }

    private static void AssertWireQueriesEqualPinned(string payload)
    {
        Assert.True(PinnedWireFacts.TryGetValue(payload, out var expected), "Unpinned payload: " + EscapeForPins(payload));
        var fields = expected.Split((char)31);
        var actual = new System.Collections.Generic.List<string>();
        actual.Add("neg=" + ProbeWireQuery(() => Utf8OwnedCharClass.IsNegated(payload).ToString()));
        actual.Add("sub=" + ProbeWireQuery(() => Utf8OwnedCharClass.IsSubtraction(payload).ToString()));
        actual.Add("empty=" + ProbeWireQuery(() => Utf8OwnedCharClass.IsEmpty(payload).ToString()));
        actual.Add("sing=" + ProbeWireQuery(() => Utf8OwnedCharClass.IsSingleton(payload).ToString()));
        actual.Add("ascii=" + ProbeWireQuery(() => Utf8OwnedCharClass.IsAscii(payload).ToString()));
        actual.Add("enum=" + ProbeWireQuery(() => Utf8OwnedCharClass.CanEasilyEnumerateSetContents(payload).ToString()));
        actual.Add("singchar=" + ProbeWireQuery(() => "char:" + ((int)Utf8OwnedCharClass.SingletonChar(payload)).ToString()));
        actual.Add("chars=" + ProbeWireQuery(() => "chars:" + EscapeForPins(new string(Utf8OwnedCharClass.GetSetChars(payload)))));
        actual.Add("single=" + ProbeWireQuery(() => { var ok = Utf8OwnedCharClass.TryGetSingleRange(payload, out var first, out var last); return ok ? "ok:" + ((int)first).ToString() + ":" + ((int)last).ToString() : "no"; }));
        actual.Add("double=" + ProbeWireQuery(() => { var ok = Utf8OwnedCharClass.TryGetDoubleRange(payload, out var firstRange, out var secondRange); return ok ? "ok:" + ((int)firstRange.First).ToString() + ":" + ((int)firstRange.Last).ToString() + ":" + ((int)secondRange.First).ToString() + ":" + ((int)secondRange.Last).ToString() : "no"; }));
        actual.Add("cats=" + ProbeWireQuery(() => { var ok = Utf8OwnedCharClass.TryGetOnlyCategories(payload, out var categories); return ok ? "ok:" + EscapeForPins(categories) : "no"; }));
        actual.Add("count=" + ProbeWireQuery(() => { var ok = Utf8OwnedCharClass.TryGetSetCharCount(payload, out var count); return ok ? "ok:" + count.ToString() : "no"; }));
        Assert.Equal(fields[0], actual[0]);
        Assert.Equal(fields[1], actual[1]);
        Assert.Equal(fields[2], actual[2]);
        Assert.Equal(fields[3], actual[3]);
        Assert.Equal(fields[4], actual[4]);
        Assert.Equal(fields[5], actual[5]);
        Assert.Equal(fields[6], actual[6]);
        Assert.Equal(fields[7], actual[7]);
        Assert.Equal(fields[8], actual[8]);
        Assert.Equal(fields[9], actual[9]);
        Assert.Equal(fields[10], actual[10]);
        Assert.Equal(fields[11], actual[11]);
        var actualCuts = new System.Collections.Generic.List<string>();
        for (var cut = 0; cut <= payload.Length; cut++)
        {
            var truncated = payload.Substring(0, cut);
            actualCuts.Add(ProbeWireQuery(() => Utf8OwnedCharClass.CharInClass((char)65, truncated).ToString()) + "/" + ProbeWireQuery(() => Utf8OwnedCharClass.CharInClassBase((char)65, truncated).ToString()));
        }
        var expectedCuts = new System.Collections.Generic.List<string>();
        expectedCuts.Add(fields[12].Substring("CUTS ".Length));
        for (var i = 13; i < fields.Length; i++)
        {
            expectedCuts.Add(fields[i]);
        }
        Assert.Equal(expectedCuts, actualCuts);
    }


    private static string EscapeForPins(string value)
    {
        var builder = new System.Text.StringBuilder();
        foreach (var c in value)
        {
            builder.Append((char)92);
            builder.Append("u");
            builder.Append(((int)c).ToString("X4"));
        }

        return builder.ToString();
    }

    private static string ProbeWireQuery(System.Func<string> render)
    {
        try
        {
            return "value:" + render();
        }
        catch (System.Exception ex)
        {
            return "throws:" + ex.GetType().FullName + ":" + ((ex as System.ArgumentException)?.ParamName ?? string.Empty);
        }
    }

